class Temperature
  def self.from_fahrenheit(f) = new((f - 32) * 5.0 / 9)
  def self.from_kelvin(k)     = new(k - 273.15)

  def initialize(celsius) = @celsius = Float(celsius)
  attr_reader :celsius
  private_class_method :new          # force callers through the named routes
end
